describe('Modal Content Scroll Independent Overflow', () => {
  beforeEach(() => {
    cy.visit('/modal-dialog');
  });

  it('should scroll modal content independently when it overflows horizontally', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Scrollable Modal');

    // Trigger horizontal overflow
    cy.get('[data-testid="modal-content"]').then((modal) => {
      modal.find('[data-testid="scrollable-content"]').then((content) => {
        content.find('[data-testid="item-1"]').then((item) => {
          item.click();
        });
      });
    });

    // Verify scrollbar appears
    cy.get('[data-testid="modal-scrollbar"]').should('be.visible');

    // Verify content is scrollable
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-y', 'auto');
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-x', 'auto');

    // Verify content is not scrollable vertically
    cy.get('[data-testid="modal-content"]').should('not.have.css', 'overflow-y');

    // Verify scroll position is correct
    cy.get('[data-testid="modal-content"]').then((modal) => {
      cy.wrap(modal).then((modal) => {
        cy.wrap(modal.scrollTop()).should('equal', 0);
        cy.wrap(modal.scrollLeft()).should('equal', 0);
      });
    });

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should scroll modal content independently when it overflows vertically', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Trigger vertical overflow
    cy.get('[data-testid="modal-content"]').then((modal) => {
      modal.find('[data-testid="scrollable-content"]').then((content) => {
        content.find('[data-testid="item-1"]').then((item) => {
          item.click();
        });
      });
    });

    // Verify scrollbar appears
    cy.get('[data-testid="modal-scrollbar"]').should('be.visible');

    // Verify content is scrollable vertically
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-y', 'auto');

    // Verify content is not scrollable horizontally
    cy.get('[data-testid="modal-content"]').should('not.have.css', 'overflow-x');

    // Verify scroll position is correct
    cy.get('[data-testid="modal-content"]').then((modal) => {
      cy.wrap(modal.scrollTop()).should('equal', 0);
      cy.wrap(modal.scrollLeft()).should('equal', 0);
    });

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });
});
